<script>
// === MOBILE MENU ===
function toggleMenu() {
  document.getElementById('hamburger').classList.toggle('active');
  document.getElementById('mobileNav').classList.toggle('open');
  document.body.style.overflow =
    document.getElementById('mobileNav').classList.contains('open') ? 'hidden' : '';
}

function closeMenu() {
  document.getElementById('hamburger').classList.remove('active');
  document.getElementById('mobileNav').classList.remove('open');
  document.body.style.overflow = '';
}

document.querySelectorAll('.mobile-nav a[href^="#"]').forEach(link => {
  link.addEventListener('click', closeMenu);
});

// === HEADER SCROLL SHADOW ===
window.addEventListener('scroll', () => {
  document.getElementById('header').classList.toggle('scrolled', window.scrollY > 10);
});

// === DONATION MODAL ===
var selectedAmount = null;

function openModal() {
  document.getElementById('modalOverlay').classList.add('open');
  document.body.style.overflow = 'hidden';
  selectedAmount = null;
  document.querySelectorAll('.amount-btn').forEach(b => b.classList.remove('selected'));
  document.getElementById('customAmount').value = '';
}

function closeModal() {
  document.getElementById('modalOverlay').classList.remove('open');
  document.body.style.overflow = '';
}

document.getElementById('modalOverlay').addEventListener('click', function(e) {
  if (e.target === this) closeModal();
});

document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') closeModal();
});

function selectAmount(btn) {
  document.querySelectorAll('.amount-btn').forEach(b => b.classList.remove('selected'));
  btn.classList.add('selected');
  selectedAmount = btn.dataset.amount;
  document.getElementById('customAmount').value = '';
}

function onCustomAmount(val) {
  if (val) {
    document.querySelectorAll('.amount-btn').forEach(b => b.classList.remove('selected'));
    selectedAmount = val;
  }
}

function submitDonation() {
  var amount = selectedAmount || document.getElementById('customAmount').value;
  if (!amount || amount <= 0) {
    alert('Please select or enter a donation amount.');
    return;
  }
  alert('Thank you for your generous donation of $' + amount + '!\n\nYou will be redirected to our secure payment page.');
  closeModal();
}

// === IMPACT COUNTER ANIMATION ===
function animateCounters() {
  var counters = document.querySelectorAll('.impact-number [data-count]');
  counters.forEach(function(el) {
    if (el.dataset.animated) return;
    var target = parseInt(el.dataset.count);
    var duration = 2000;
    var start = null;

    function easeOut(t) { return 1 - Math.pow(1 - t, 3); }

    function step(timestamp) {
      if (!start) start = timestamp;
      var progress = Math.min((timestamp - start) / duration, 1);
      var eased = easeOut(progress);
      var current = Math.floor(eased * target);
      el.textContent = current;
      if (progress < 1) {
        requestAnimationFrame(step);
      } else {
        el.textContent = target;
        el.dataset.animated = 'true';
      }
    }

    requestAnimationFrame(step);
  });
}

var impactObserved = false;
var impactObserver = new IntersectionObserver(function(entries) {
  entries.forEach(function(entry) {
    if (entry.isIntersecting && !impactObserved) {
      impactObserved = true;
      animateCounters();
      impactObserver.disconnect();
    }
  });
}, { threshold: 0.4 });

var impactSection = document.getElementById('impact');
if (impactSection) impactObserver.observe(impactSection);

// === PROGRAM ACCORDION ===
function toggleAccordion(header) {
  var item = header.parentElement;
  var isOpen = item.classList.contains('open');

  // Close all
  document.querySelectorAll('.program-item').forEach(function(el) {
    el.classList.remove('open');
    el.querySelector('.program-header').setAttribute('aria-expanded', 'false');
  });

  // Open clicked (if not already open)
  if (!isOpen) {
    item.classList.add('open');
    header.setAttribute('aria-expanded', 'true');
  }
}

// === NEWS CAROUSEL ===
(function() {
  var track = document.getElementById('newsTrack');
  var cards = track.querySelectorAll('.news-card');
  var dotsContainer = document.getElementById('newsDots');
  var prevBtn = document.getElementById('newsPrev');
  var nextBtn = document.getElementById('newsNext');
  var currentIndex = 0;
  var totalCards = cards.length;
  var visibleCards = 2; // default desktop

  function getVisibleCards() {
    if (window.innerWidth <= 768) return 1;
    return 2;
  }

  function getMaxIndex() {
    visibleCards = getVisibleCards();
    return Math.max(0, totalCards - visibleCards);
  }

  function goToSlide(index) {
    var max = getMaxIndex();
    currentIndex = Math.max(0, Math.min(index, max));
    var cardWidth = cards[0].getBoundingClientRect().width;
    var gap = 24;
    track.style.transform = 'translateX(-' + (currentIndex * (cardWidth + gap)) + 'px)';
    updateDots();
    prevBtn.disabled = currentIndex === 0;
    nextBtn.disabled = currentIndex >= max;
  }

  // Create dots
  function createDots() {
    dotsContainer.innerHTML = '';
    var count = getMaxIndex() + 1;
    for (var i = 0; i < count; i++) {
      var dot = document.createElement('button');
      dot.className = 'news-dot';
      dot.setAttribute('aria-label', 'News page ' + (i + 1));
      dot.addEventListener('click', (function(idx) { return function() { goToSlide(idx); }; })(i));
      dotsContainer.appendChild(dot);
    }
  }

  function updateDots() {
    var dots = dotsContainer.querySelectorAll('.news-dot');
    dots.forEach(function(d, i) { d.classList.toggle('active', i === currentIndex); });
  }

  prevBtn.addEventListener('click', function() { goToSlide(currentIndex - 1); });
  nextBtn.addEventListener('click', function() { goToSlide(currentIndex + 1); });

  var resizeTimer;
  window.addEventListener('resize', function() {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(function() {
      createDots();
      goToSlide(0);
    }, 200);
  });

  // Initialise
  createDots();
  goToSlide(0);
  prevBtn.disabled = true;
})();
</script>

